import { createDemoStore, demoSchools } from './demoStore.mjs';
import { instructorTablePage } from './instructorTable.mjs';

export function initDashboard(renderPage) {
  'use strict';
  let TZ = 'Asia/Makassar';
  const icons = {dashboard:'layout',permintaan:'message',jadwal:'calendar',murid:'users',instruktur:'user',mobil:'car',paket:'package',laporan:'chart',pengaturan:'settings'};
  const navGroups = [{label:'MENU UTAMA',items:[['dashboard','Ringkasan'],['permintaan','Permintaan'],['jadwal','Jadwal'],['murid','Murid']]},{label:'PENGELOLAAN',items:[['instruktur','Instruktur'],['mobil','Mobil'],['paket','Paket']]},{label:'LAINNYA',items:[['laporan','Laporan'],['pengaturan','Pengaturan']]}];
  const labels = Object.fromEntries(navGroups.flatMap(g => g.items));
  const ico=(name,extra='')=>`<svg class="icon ${extra}" aria-hidden="true"><use href="#i-${name}"/></svg>`;
  const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const attr=esc;
  const isoDay=(d=new Date())=>new Intl.DateTimeFormat('sv-SE',{timeZone:TZ,year:'numeric',month:'2-digit',day:'2-digit'}).format(d);
  const moveDay=(day,delta)=>{const d=new Date(`${day}T12:00:00Z`);d.setUTCDate(d.getUTCDate()+delta);return d.toISOString().slice(0,10);};
  const dayOfWeek=day=>new Date(`${day}T12:00:00Z`).getUTCDay();
  const weekStart=day=>moveDay(day,-((dayOfWeek(day)+6)%7));
  const fmtDate=(day,opts={weekday:'long',day:'numeric',month:'long',year:'numeric'})=>new Intl.DateTimeFormat('id-ID',{timeZone:'UTC',...opts}).format(new Date(`${day}T12:00:00Z`));
  const shortDay=day=>fmtDate(day,{day:'numeric',month:'short'});
  const nowWita=()=>new Intl.DateTimeFormat('id-ID',{timeZone:TZ,hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date());
  const uid=prefix=>prefix+Math.random().toString(36).slice(2,8);
  const demoStore=createDemoStore(localStorage);
  const seed=()=>{
    const t=isoDay();
    return {
      leads:[
        {id:'L1',name:'Dinda Maharani',phone:'',interest:'Matic · Pemanasan',time:'Pagi',status:'Baru',source:'WhatsApp (manual)',date:t,notes:'Ingin mulai dari dasar.'},
        {id:'L2',name:'Andi Pratama',phone:'',interest:'Manual',time:'Sore',status:'Baru',source:'Input admin',date:t,notes:''},
        {id:'L3',name:'Nadia Putri',phone:'',interest:'Matic · Makin Lancar',time:'Akhir pekan',status:'Dihubungi',source:'WhatsApp (manual)',date:moveDay(t,-1),notes:'Preferensi instruktur perempuan, sesuai ketersediaan.'},
        {id:'L4',name:'Reza Firdaus',phone:'',interest:'Kombinasi',time:'Malam',status:'Menunggu keputusan',source:'Input admin',date:moveDay(t,-1),notes:''},
        {id:'L5',name:'Siti Aulia',phone:'',interest:'Matic',time:'Siang',status:'Dikonversi',source:'WhatsApp (manual)',date:moveDay(t,-2),notes:''},
        {id:'L6',name:'Fajar Hidayat',phone:'',interest:'Manual',time:'Pagi',status:'Tidak lanjut',source:'Input admin',date:moveDay(t,-3),notes:''}
      ],
      students:[
        {id:'S1',name:'Alya Ramadhani',phone:'',package:'Makin Lancar · Matic',done:3,total:8,status:'Aktif'},
        {id:'S2',name:'Bima Saputra',phone:'',package:'Pemanasan · Manual',done:1,total:4,status:'Aktif'},
        {id:'S3',name:'Nabila Zahra',phone:'',package:'Siap Jalan · Matic',done:7,total:12,status:'Aktif'},
        {id:'S4',name:'Rizky Firmansyah',phone:'',package:'Makin Lancar · Manual',done:5,total:8,status:'Aktif'},
        {id:'S5',name:'Putri Ananda',phone:'',package:'Pemanasan · Matic',done:4,total:4,status:'Selesai'},
        {id:'S6',name:'Siti Aulia',phone:'',package:'Pemanasan · Matic',done:0,total:4,status:'Aktif'}
      ],
      instructors:[
        {id:'I1',name:'Instruktur A',skills:'Matic & Manual',active:true,notes:'Identitas dan jadwal belum diverifikasi'},
        {id:'I2',name:'Instruktur B',skills:'Matic',active:true,notes:'Identitas dan jadwal belum diverifikasi'},
        {id:'I3',name:'Instruktur C',skills:'Manual',active:true,notes:'Identitas dan jadwal belum diverifikasi'}
      ],
      cars:[
        {id:'C1',name:'Unit Matic 01',trans:'Matic',active:true},
        {id:'C2',name:'Unit Manual 01',trans:'Manual',active:true},
        {id:'C3',name:'Unit Matic 02',trans:'Matic',active:true}
      ],
      sessions:[
        {id:'B1',studentId:'S1',date:t,start:'08:00',end:'09:00',trans:'Matic',instructorId:'I1',carId:'C1',status:'Terkonfirmasi'},
        {id:'B2',studentId:'S2',date:t,start:'10:00',end:'11:00',trans:'Manual',instructorId:'I3',carId:'C2',status:'Terkonfirmasi'},
        {id:'B3',studentId:'S3',date:t,start:'13:00',end:'14:00',trans:'Matic',instructorId:'I2',carId:'C3',status:'Menunggu konfirmasi'},
        {id:'B4',studentId:'S4',date:t,start:'15:30',end:'16:30',trans:'Manual',instructorId:'I1',carId:'C2',status:'Terkonfirmasi'},
        {id:'B5',studentId:'S6',date:moveDay(t,1),start:'09:00',end:'10:00',trans:'Matic',instructorId:'I2',carId:'C1',status:'Menunggu konfirmasi'},
        {id:'B6',studentId:'S1',date:moveDay(t,2),start:'08:00',end:'09:00',trans:'Matic',instructorId:'I1',carId:'C1',status:'Terkonfirmasi'},
        {id:'B7',studentId:'S2',date:moveDay(t,-1),start:'10:00',end:'11:00',trans:'Manual',instructorId:'I3',carId:'C2',status:'Selesai'}
      ],
      settings:{hoursFrom:'',hoursTo:'',businessPhone:'6282358777800'}
    };
  };
  function readDB(){try{return demoStore.load(activeSchool.id,seed);}catch(e){return seed();}}
  const schools=demoSchools;
  let activeSchool=schools.find(s=>s.id===location.pathname.split('/')[2])||schools.find(s=>s.id===localStorage.getItem('active-demo-school'))||schools[0];
  TZ=activeSchool.timeZone;
  let db=readDB();
  const persist=()=>{try{demoStore.save(activeSchool.id,db);}catch(e){}};
  let ui={page:labels[location.pathname.split('/')[4]]?location.pathname.split('/')[4]:'dashboard',date:isoDay(),view:window.innerWidth<=690?'hari':'minggu',query:'',leadStatus:'Semua status',leadTrans:'Semua jenis',scheduleFilter:'Semua status',studentQuery:'',instructorQuery:'',instructorSort:'name',instructorDirection:'asc',instructorPage:1};
  const getStudent=id=>db.students.find(x=>x.id===id);
  const getInstructor=id=>db.instructors.find(x=>x.id===id);
  const getCar=id=>db.cars.find(x=>x.id===id);
  const studentName=id=>getStudent(id)?.name||'Murid dihapus';
  const instrName=id=>getInstructor(id)?.name||'Belum dipilih';
  const carName=id=>getCar(id)?.name||'Belum dipilih';
  const firstTwo=name=>name.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
  const avatar=(name,kind='neutral')=>`<span class="avatar ${kind}">${esc(firstTwo(name))}</span>`;
  const badgeStatus=s=>{const c=({'Baru':'warning','Menunggu keputusan':'warning','Menunggu konfirmasi':'warning','Dihubungi':'info','Aktif':'info','Dikonversi':'success','Terkonfirmasi':'success','Selesai':'success','Tidak lanjut':'neutral','Batal':'danger','Dibatalkan':'danger','Tidak hadir':'danger'})[s]||'neutral';return `<span class="badge ${c}">${esc(s)}</span>`;};
  const head=(label,sub,actions='',eyebrow='OPERASIONAL')=>`<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${esc(label)}</h1><p class="page-sub">${sub}</p></div><div class="heading-actions">${actions}</div></div>`;
  const demo=()=>`<div class="demo-banner">${ico('info')}<p><strong>Mode demo — data simulasi.</strong> Nama murid, instruktur, unit, angka, dan jadwal di bawah hanya contoh tampilan. Data baru tersimpan lokal di browser ini; belum ada API, WhatsApp sync, atau konfirmasi nyata.</p><span class="demo-tag">${ico('check','sm')} SIMULASI</span></div>`;
  const noData=(what,action='')=>`<div class="empty"><span class="empty-illustration">${ico('clipboard','lg')}</span><strong>${esc(what)}</strong><p>Belum ada data yang sesuai. Periksa filter atau tambahkan data baru untuk mencoba prototipe.</p>${action}</div>`;
  const smallDate=d=>fmtDate(d,{day:'numeric',month:'short',year:'numeric'});
  const statusClass=s=>['Terkonfirmasi','Selesai'].includes(s)?'confirmed':['Menunggu konfirmasi'].includes(s)?'pending':'canceled';
  const isVisibleSession=s=>ui.scheduleFilter==='Semua status'||s.status===ui.scheduleFilter;
  function sidebarNav(){
    document.getElementById('sidebarNav').innerHTML=navGroups.map(g=>`<div class="nav-group"><div class="nav-title">${g.label}</div>${g.items.map(([key,name])=>`<button type="button" class="nav-link ${ui.page===key?'active':''}" data-page="${key}" ${ui.page===key?'aria-current="page"':''}>${ico(icons[key])}<span>${name}</span>${key==='permintaan'?`<span class="nav-count">${db.leads.filter(x=>x.status==='Baru').length}</span>`:''}</button>`).join('')}</div>`).join('');
    document.getElementById('mobileTabs').innerHTML=['dashboard','permintaan','jadwal','murid'].map(key=>`<button class="mobile-tab ${ui.page===key?'active':''}" type="button" data-page="${key}" ${ui.page===key?'aria-current="page"':''}>${ico(icons[key])}<span>${labels[key]}</span></button>`).join('');
  }
  function render(){sidebarNav();document.getElementById('breadcrumb').textContent=labels[ui.page];document.title=`${labels[ui.page]} | ${activeSchool.name}`;document.getElementById('headerClock').textContent=`${nowWita()} ${TZ==='Asia/Makassar'?'WITA':TZ==='Asia/Jakarta'?'WIB':TZ}`; const pages={dashboard:renderDashboard,permintaan:renderLeads,jadwal:renderSchedule,murid:renderStudents,instruktur:renderInstructors,mobil:renderCars,paket:renderPackages,laporan:renderReports,pengaturan:renderSettings};renderPage(ui.page,(pages[ui.page]||renderDashboard)());}
  function metric(name,value,foot,iconName,cls=''){return `<div class="metric ${cls}"><div class="metric-top"><span class="metric-label">${name}</span><span class="metric-icon">${ico(iconName)}</span></div><div class="metric-value">${value}</div><div class="metric-foot">${foot}</div></div>`;}
  const orderedSessions=arr=>[...arr].sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start));
  const agendaEntry=s=>`<div class="agenda-entry"><div class="agenda-time">${esc(s.start)}</div><div class="agenda-rule ${statusClass(s.status)}"></div><div class="agenda-detail"><div class="agenda-primary"><strong>${esc(studentName(s.studentId))}</strong>${badgeStatus(s.status)}</div><div class="agenda-meta"><span>${esc(s.start)}–${esc(s.end)}</span><i class="dot-sep"></i><span>${esc(s.trans)}</span><i class="dot-sep"></i><span>${esc(instrName(s.instructorId))}</span><i class="dot-sep"></i><span>${esc(carName(s.carId))}</span></div></div><button class="agenda-btn" type="button" data-session="${attr(s.id)}" aria-label="Lihat sesi ${attr(studentName(s.studentId))}">${ico('chevron-right','sm')}</button></div>`;
  function renderDashboard(){
    const today=isoDay(), sess=orderedSessions(db.sessions.filter(x=>x.date===today&&!['Dibatalkan','Tidak hadir'].includes(x.status))), newLeads=db.leads.filter(x=>x.status==='Baru'), pending=db.sessions.filter(x=>x.status==='Menunggu konfirmasi'), students=db.students.filter(x=>x.status==='Aktif');
    return head('Ringkasan',`${fmtDate(today)} · Aktivitas dan jadwal kursus mengemudi.`,`<button class="btn btn-quiet" data-page="permintaan">${ico('message','sm')} Permintaan</button><button class="btn btn-primary" data-action="add-session">${ico('plus','sm')} Jadwalkan sesi</button>`)+demo()+`<div class="metrics">${metric('Permintaan baru',newLeads.length,'Belum ditindaklanjuti','message','hot')}${metric('Sesi hari ini',sess.length,`Agenda ${shortDay(today)}`,'calendar')}${metric('Menunggu konfirmasi',pending.length,'Sesi yang belum final','clock','yellow')}${metric('Murid aktif',students.length,'Status aktif pada contoh data','users')}</div><div class="layout-two"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Agenda hari ini</h2><p class="panel-sub">${fmtDate(today)} · WITA</p></div><button class="inline-link" data-page="jadwal">Lihat jadwal ${ico('arrow','sm')}</button></div><div class="panel-body">${sess.length?sess.map(agendaEntry).join(''):noData('Belum ada sesi hari ini',`<button class="btn btn-sm btn-primary" data-action="add-session">Tambah sesi</button>`)}</div></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Perlu ditindaklanjuti</h2><p class="panel-sub">Tindakan yang menunggu admin</p></div><span class="badge warning">${newLeads.length+pending.length} tugas</span></div><div class="panel-body">${newLeads.length?`<div class="action-item"><div class="action-icon">${ico('message')}</div><div><strong>${newLeads.length} permintaan belum direspons</strong><p>Tinjau dan catat hasil tindak lanjut WhatsApp secara manual.</p><button class="inline-link" data-page="permintaan">Buka permintaan ${ico('arrow','sm')}</button></div></div>`:''}${pending.length?`<div class="action-item"><div class="action-icon">${ico('clock')}</div><div><strong>${pending.length} sesi menunggu konfirmasi</strong><p>Pastikan instruktur, mobil, dan waktu sebelum menetapkan status.</p><button class="inline-link" data-page="jadwal">Periksa jadwal ${ico('arrow','sm')}</button></div></div>`:''}<div class="action-item"><div class="action-icon">${ico('info')}</div><div><strong>Verifikasi data operasional</strong><p>Jam layanan, durasi paket, dan identitas instruktur masih berupa contoh.</p><button class="inline-link" data-page="pengaturan">Lihat pengaturan ${ico('arrow','sm')}</button></div></div></div></section></div><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Permintaan terbaru</h2><p class="panel-sub">Daftar singkat calon murid</p></div><button class="inline-link" data-page="permintaan">Lihat semua ${ico('arrow','sm')}</button></div>${leadsTable(orderedLeads().slice(0,5),false)}</section>`;
  }
  const orderedLeads=()=>[...db.leads].sort((a,b)=>b.date.localeCompare(a.date));
  const leadsTable=(arr,full=true)=>`<div class="table-wrap"><table><thead><tr><th>Calon murid</th><th>Minat kursus</th>${full?'<th>Preferensi waktu</th>':''}<th>Status</th><th>Diterima</th><th>Aksi</th></tr></thead><tbody>${arr.map(l=>`<tr><td><div class="name-cell">${avatar(l.name)}<span><strong>${esc(l.name)}</strong><small>${esc(l.source)}</small></span></div></td><td>${esc(l.interest)}</td>${full?`<td>${esc(l.time||'Belum dipilih')}</td>`:''}<td>${badgeStatus(l.status)}</td><td class="no-wrap subtle">${smallDate(l.date)}</td><td><button class="inline-link" data-lead="${attr(l.id)}">Detail ${ico('chevron-right','sm')}</button></td></tr>`).join('')}</tbody></table></div><div class="record-list">${arr.map(l=>`<article class="record"><div class="record-top"><div class="resource-main">${avatar(l.name)}<div><strong>${esc(l.name)}</strong><div class="record-meta">${esc(l.interest)}</div></div></div>${badgeStatus(l.status)}</div><div class="record-meta"><span>${esc(l.source)}</span><span>${esc(l.time||'Belum ada waktu')}</span><span>${smallDate(l.date)}</span></div><div class="record-bottom"><span class="subtle" style="font-size:10px">Kontak: ${l.phone?'tersimpan':'belum diisi'}</span><button class="inline-link" data-lead="${attr(l.id)}">Lihat detail ${ico('arrow','sm')}</button></div></article>`).join('')}</div>`;
  function renderLeads(){
    const query=ui.query.toLowerCase();const all=orderedLeads().filter(x=>(x.name+' '+x.interest+' '+x.phone).toLowerCase().includes(query)&&(ui.leadStatus==='Semua status'||x.status===ui.leadStatus)&&(ui.leadTrans==='Semua jenis'||x.interest.toLowerCase().includes(ui.leadTrans.toLowerCase())));
    return head('Permintaan',`Kelola calon murid dari pesan WhatsApp atau input manual. <strong>${db.leads.length} data contoh</strong>.`,`<button class="btn btn-primary" data-action="add-lead">${ico('plus','sm')} Tambah permintaan</button>`)+demo()+`<section class="panel"><div class="toolbar"><div class="toolbar-left"><label class="field-search">${ico('search','sm')}<input id="leadSearch" type="search" placeholder="Cari nama atau minat..." value="${attr(ui.query)}" aria-label="Cari permintaan"/></label></div><div class="toolbar-right"><select id="leadStatus" class="field-select" aria-label="Filter status">${['Semua status','Baru','Dihubungi','Menunggu keputusan','Dikonversi','Tidak lanjut'].map(x=>`<option ${ui.leadStatus===x?'selected':''}>${x}</option>`).join('')}</select><select id="leadTrans" class="field-select" aria-label="Filter transmisi">${['Semua jenis','Matic','Manual','Kombinasi'].map(x=>`<option ${ui.leadTrans===x?'selected':''}>${x}</option>`).join('')}</select></div></div>${all.length?leadsTable(all):noData('Tidak ditemukan permintaan',`<button class="btn btn-primary btn-sm" data-action="clear-filters">Hapus filter</button>`)}</section>`;
  }
  function renderStudents(){const q=ui.studentQuery.toLowerCase();const arr=db.students.filter(s=>(s.name+' '+s.package).toLowerCase().includes(q));return head('Murid','Daftar peserta, paket contoh, serta progres latihan yang dicatat manual.',`<button class="btn btn-primary" data-action="add-student">${ico('plus','sm')} Tambah murid</button>`)+demo()+`<section class="panel"><div class="toolbar"><div class="toolbar-left"><label class="field-search">${ico('search','sm')}<input type="search" id="studentSearch" placeholder="Cari nama atau paket..." value="${attr(ui.studentQuery)}" aria-label="Cari murid"/></label></div><span class="muted" style="font-size:11px">${arr.length} murid</span></div>${arr.length?`<div class="table-wrap"><table><thead><tr><th>Murid</th><th>Paket contoh</th><th>Progres sesi</th><th>Status</th><th>Sesi berikutnya</th><th>Aksi</th></tr></thead><tbody>${arr.map(s=>{const next=orderedSessions(db.sessions.filter(b=>b.studentId===s.id&&b.date>=isoDay()&&!['Dibatalkan','Selesai'].includes(b.status)))[0];return `<tr><td><div class="name-cell">${avatar(s.name,'blue')}<span><strong>${esc(s.name)}</strong><small>${esc(s.id)}</small></span></div></td><td>${esc(s.package)}</td><td><strong>${s.done}/${s.total}</strong> sesi</td><td>${badgeStatus(s.status)}</td><td>${next?`${shortDay(next.date)}, ${next.start}`:'Belum dijadwalkan'}</td><td><button class="inline-link" data-student="${attr(s.id)}">Detail ${ico('arrow','sm')}</button></td></tr>`;}).join('')}</tbody></table></div><div class="record-list">${arr.map(s=>`<article class="record"><div class="record-top"><div class="resource-main">${avatar(s.name,'blue')}<div><strong>${esc(s.name)}</strong><div class="record-meta">${esc(s.package)}</div></div></div>${badgeStatus(s.status)}</div><div class="record-bottom"><span style="font-size:11px">Progres: <strong>${s.done}/${s.total} sesi</strong></span><button class="inline-link" data-student="${attr(s.id)}">Detail ${ico('arrow','sm')}</button></div></article>`).join('')}</div>`:noData('Murid tidak ditemukan')}</section>`;}
  function dateNavTitle(){if(ui.view==='minggu'){const start=weekStart(ui.date);const end=moveDay(start,6);return `${shortDay(start)} – ${shortDay(end)}`;}return fmtDate(ui.date,{weekday:'short',day:'numeric',month:'long',year:'numeric'});}
  function eventCard(s){return `<button class="event-card ${statusClass(s.status)==='pending'?'pending':statusClass(s.status)==='canceled'?'canceled':''}" type="button" data-session="${attr(s.id)}" title="${attr(studentName(s.studentId))} · ${attr(s.status)}"><span class="event-time">${esc(s.start)}–${esc(s.end)}</span><strong>${esc(studentName(s.studentId))}</strong><small>${esc(s.trans)} · ${esc(carName(s.carId))}</small></button>`;}
  function groupedAgenda(arr,dates){return dates.map(day=>{const group=arr.filter(s=>s.date===day);return `<div class="date-divider">${fmtDate(day,{weekday:'long',day:'numeric',month:'long'})}${day===isoDay()?' · Hari ini':''}</div>${group.length?group.map(agendaEntry).join(''):`<div class="day-empty" style="padding:12px 0;text-align:left">Belum ada sesi</div>`}`;}).join('');}
  function renderSchedule(){
    const start=weekStart(ui.date),days=Array.from({length:7},(_,i)=>moveDay(start,i));const filtered=orderedSessions(db.sessions.filter(isVisibleSession));const dates=ui.view==='minggu'?days:ui.view==='hari'?[ui.date]:Array.from({length:14},(_,i)=>moveDay(ui.date,i));
    const weekGrid=`<div class="week-grid">${days.map(day=>{const ds=filtered.filter(s=>s.date===day);return `<div class="day-col"><div class="day-head"><small>${fmtDate(day,{weekday:'short'})}</small><span class="day-number ${day===isoDay()?'today':''}">${Number(day.slice(8))}</span></div>${ds.length?ds.map(eventCard).join(''):`<div class="day-empty">—</div>`}</div>`;}).join('')}</div><div class="mobile-week-list">${groupedAgenda(filtered,days)}</div>`;
    return head('Jadwal latihan','Atur waktu, instruktur, dan mobil. Penjadwalan di sini hanya simulasi lokal.',`<button class="btn btn-primary" data-action="add-session">${ico('plus','sm')} Jadwalkan sesi</button>`)+demo()+`<section class="panel"><div class="calendar-tools"><div class="date-nav"><button class="icon-control" data-action="prev-date" aria-label="Periode sebelumnya">${ico('chevron-left','sm')}</button><button class="btn btn-quiet btn-sm" data-action="today">Hari ini</button><button class="icon-control" data-action="next-date" aria-label="Periode berikutnya">${ico('chevron-right','sm')}</button><h3>${esc(dateNavTitle())}</h3></div><div class="segmented" aria-label="Tampilan jadwal">${[['hari','Hari'],['minggu','Minggu'],['daftar','Daftar']].map(([key,l])=>`<button data-view="${key}" class="${ui.view===key?'active':''}" aria-pressed="${ui.view===key}">${l}</button>`).join('')}</div></div><div class="toolbar"><div class="legend"><span class="legend-item"><i class="legend-dot"></i> Terkonfirmasi / selesai</span><span class="legend-item"><i class="legend-dot pending"></i> Menunggu</span><span class="legend-item"><i class="legend-dot canceled"></i> Dibatalkan</span></div><select id="scheduleFilter" class="field-select" aria-label="Filter status jadwal">${['Semua status','Terkonfirmasi','Menunggu konfirmasi','Selesai','Dibatalkan'].map(x=>`<option ${ui.scheduleFilter===x?'selected':''}>${x}</option>`).join('')}</select></div>${ui.view==='minggu'?weekGrid:`<div class="agenda-list-panel">${groupedAgenda(filtered,dates)}</div>`}</section><p style="font-size:11px;color:#626464;margin-top:15px">${ico('info','sm')} Konflik instruktur dan mobil dicek pada data di browser ini. Validasi transaksi server tetap wajib sebelum sistem digunakan untuk booking nyata.</p>`;
  }
  function renderInstructors(){const result=instructorTablePage(db.instructors,{query:ui.instructorQuery,sort:ui.instructorSort,direction:ui.instructorDirection,page:ui.instructorPage,pageSize:10});ui.instructorPage=result.page;const sortButton=(key,label)=>`<button type="button" class="table-sort" data-action="sort-instructor" data-sort="${key}" aria-label="Urutkan ${label}">${label} <span aria-hidden="true">${ui.instructorSort===key?(ui.instructorDirection==='asc'?'↑':'↓'):'↕'}</span></button>`;return head('Instruktur','Daftar simulasi kompetensi mengemudi dan status penugasan.',`<button class="btn btn-quiet" data-page="jadwal">${ico('calendar','sm')} Lihat jadwal</button><button class="btn btn-primary" data-action="add-instructor">${ico('plus','sm')} Tambah instruktur</button>`)+demo()+`<section class="panel instructor-panel"><div class="instructor-toolbar"><label class="field-search">${ico('search','sm')}<input id="instructorSearch" type="search" placeholder="Cari nama atau catatan..." value="${attr(ui.instructorQuery)}" aria-label="Cari instruktur"/></label></div>${result.total?`<div class="instructor-table-scroll"><table class="instructor-table"><thead><tr><th aria-sort="${ui.instructorSort==='name'?(ui.instructorDirection==='asc'?'ascending':'descending'):'none'}">${sortButton('name','Nama')}</th><th aria-sort="${ui.instructorSort==='transmission'?(ui.instructorDirection==='asc'?'ascending':'descending'):'none'}">${sortButton('transmission','Kompetensi')}</th><th>Catatan</th><th aria-sort="${ui.instructorSort==='status'?(ui.instructorDirection==='asc'?'ascending':'descending'):'none'}">${sortButton('status','Status')}</th><th>Aksi</th></tr></thead><tbody>${result.items.map(i=>`<tr><td><button class="instructor-name" data-instructor="${attr(i.id)}">${esc(i.name)}</button></td><td>${esc(i.skills)}</td><td class="instructor-note">${esc(i.notes||'—')}</td><td>${badgeStatus(i.active?'Aktif':'Nonaktif')}</td><td><div class="instructor-actions"><button type="button" class="table-icon-action" data-action="edit-instructor" data-id="${attr(i.id)}" aria-label="Ubah ${attr(i.name)}" title="Ubah">${ico('edit','sm')}</button><button type="button" class="table-icon-action danger" data-action="delete-instructor" data-id="${attr(i.id)}" aria-label="Hapus ${attr(i.name)}" title="Hapus">${ico('trash','sm')}</button></div></td></tr>`).join('')}</tbody></table></div>`:noData(ui.instructorQuery?'Instruktur tidak ditemukan':'Belum ada instruktur',ui.instructorQuery?'':`<button class="btn btn-primary btn-sm" data-action="add-instructor">Tambah instruktur</button>`)}<div class="instructor-footer"><span>Menampilkan ${result.total?((result.page-1)*10+1):0}–${Math.min(result.page*10,result.total)} dari ${result.total} instruktur</span><div class="instructor-pages"><button type="button" data-action="instructor-page" data-page-number="1" aria-label="Halaman pertama" ${result.page===1?'disabled':''}>«</button><button type="button" data-action="instructor-page" data-page-number="${result.page-1}" aria-label="Halaman sebelumnya" ${result.page===1?'disabled':''}>‹</button><span aria-current="page">${result.page}</span><button type="button" data-action="instructor-page" data-page-number="${result.page+1}" aria-label="Halaman berikutnya" ${result.page===result.pageCount?'disabled':''}>›</button><button type="button" data-action="instructor-page" data-page-number="${result.pageCount}" aria-label="Halaman terakhir" ${result.page===result.pageCount?'disabled':''}>»</button></div></div></section>`;}
  function renderCars(){return head('Mobil','Ketersediaan unit latihan. Setiap mobil maksimal untuk satu peserta per sesi.',`<button class="btn btn-quiet" data-page="jadwal">${ico('calendar','sm')} Lihat jadwal</button>`)+demo()+`<section class="panel"><div class="panel-head"><div><h2 class="panel-title">Unit latihan</h2><p class="panel-sub">Label unit dan jumlah mobil berikut hanya contoh</p></div></div>${db.cars.map(c=>`<div class="resource-row"><div class="resource-main"><div class="resource-ico">${ico('car','lg')}</div><div><strong>${esc(c.name)}</strong><p>Transmisi: ${esc(c.trans)}</p></div></div><div class="resource-end">${badgeStatus(c.active?'Aktif':'Nonaktif')}<button class="btn btn-quiet btn-sm" data-car="${attr(c.id)}">Detail</button></div></div>`).join('')}</section>`;}
  function renderPackages(){const packs=[{name:'Pemanasan',count:4,desc:'Simulasi paket untuk peserta yang baru mulai belajar.',featured:false},{name:'Makin Lancar',count:8,desc:'Simulasi paket untuk latihan bertahap dan konsisten.',featured:true},{name:'Siap Jalan',count:12,desc:'Simulasi paket untuk latihan dengan sesi lebih banyak.',featured:false}];return head('Paket kursus','Contoh katalog paket dan opsi layanan; nama, jumlah sesi, dan harga belum dikonfirmasi.',`<button class="btn btn-quiet" data-page="pengaturan">${ico('settings','sm')} Pengaturan</button>`)+demo()+`<div class="package-grid">${packs.map(p=>`<div class="package-card ${p.featured?'featured':''}"><div class="package-top"><span class="package-icon">${ico('package','lg')}</span><span class="badge warning">Paket demo</span></div><h3>${p.name}</h3><p>${p.desc}</p><div class="package-amount">${p.count} <small>sesi (contoh)</small></div><div class="package-footer"><span class="muted" style="font-size:11px">Harga belum tersedia</span><button class="inline-link" data-action="package-info">Detail ${ico('arrow','sm')}</button></div></div>`).join('')}</div><div class="section-head"><h2 class="section-title">Opsi layanan dari profil</h2></div><section class="panel panel-pad"><div class="resource-row" style="padding-left:0;padding-right:0"><div><strong>Matic & Manual</strong><p class="muted" style="margin:3px 0 0;font-size:11px">Jenis transmisi utama</p></div>${badgeStatus('Aktif')}</div>${['Kombinasi manual + matic','Latihan malam','Latihan hari Minggu','Opsi + SIM A (ketentuan perlu verifikasi)'].map(x=>`<div class="resource-row" style="padding-left:0;padding-right:0"><span style="font-size:12px">${esc(x)}</span><span class="badge warning">Perlu verifikasi</span></div>`).join('')}</section><p class="notice" style="margin-top:18px"><strong>Catatan:</strong> Paket 4/8/12 sesi hanya fixture untuk menguji UI, bukan penawaran resmi. Tidak ada harga, durasi, atau jaminan penerbitan SIM yang bisa disimpulkan dari brief.</p>`;}
  function renderReports(){const today=isoDay(),days=Array.from({length:7},(_,i)=>moveDay(today,i-6));const counts=days.map(d=>db.sessions.filter(s=>s.date===d&&s.status!=='Dibatalkan').length);const max=Math.max(1,...counts);const done=db.sessions.filter(s=>s.status==='Selesai').length;const cancel=db.sessions.filter(s=>s.status==='Dibatalkan').length;return head('Laporan','Ringkasan sederhana berdasarkan data simulasi yang tersimpan di browser.',`<button class="btn btn-quiet" data-action="reset-demo">${ico('rotate','sm')} Reset demo</button>`)+demo()+`<div class="metrics">${metric('Total permintaan',db.leads.length,'Semua status','message')}${metric('Sesi dijadwalkan',db.sessions.length,'Semua tanggal','calendar')}${metric('Sesi selesai',done,'Status selesai','check')}${metric('Sesi dibatalkan',cancel,'Status dibatalkan','alert')}</div><section class="panel panel-pad"><h2 class="panel-title">Sesi terjadwal · 7 hari terakhir</h2><p class="panel-sub">Jumlah sesi yang belum dibatalkan per tanggal (contoh, bukan data operasional nyata)</p><div class="stat-bars">${days.map((d,i)=>`<div class="stat-col"><b>${counts[i]}</b><div class="bar-track"><div class="bar-fill" style="height:${Math.max(1,counts[i]/max*100)}%"></div></div><small>${fmtDate(d,{weekday:'short'})}</small></div>`).join('')}</div></section><p class="notice" style="margin-top:18px"><strong>Belum ada pelaporan pendapatan.</strong> Dashboard ini belum mencatat transaksi nyata. Conversion rate, utilisasi dan pendapatan tidak ditampilkan agar tidak menghasilkan angka yang menyesatkan.</p>`;}
  function renderSettings(){return head('Pengaturan','Informasi layanan dan simulasi konfigurasi dasar operasional.',`<button class="btn btn-quiet" data-action="reset-demo">${ico('rotate','sm')} Reset data contoh</button>`)+demo()+`<div class="settings-grid"><section class="panel setting-section"><h3>Profil bisnis</h3><p>Profil sekolah demo. Verifikasi sebelum go-live.</p><div class="setting-line"><span>Nama usaha</span><strong>${esc(activeSchool.name)}</strong></div><div class="setting-line"><span>Lokasi</span><strong>${activeSchool.id==='radja'?'Jl. Pulau Kalimantan No. 7, Samarinda':esc(activeSchool.location)}</strong></div><div class="setting-line"><span>WhatsApp</span><strong>${activeSchool.id==='radja'?'0823-5877-7800':'Belum diatur'}</strong></div><div class="setting-line"><span>Jenis layanan</span><strong>Matic & Manual</strong></div></section><section class="panel setting-section"><h3>Penjadwalan (lokal)</h3><p>Atur rentang jam untuk menguji validasi formulir. Jam operasional asli belum diketahui.</p><form data-form="settings" class="form-grid"><div class="form-field"><label for="hoursFrom">Mulai pelayanan</label><input id="hoursFrom" name="hoursFrom" type="time" value="${attr(db.settings.hoursFrom||'')}" /></div><div class="form-field"><label for="hoursTo">Selesai pelayanan</label><input id="hoursTo" name="hoursTo" type="time" value="${attr(db.settings.hoursTo||'')}" /></div><div class="form-field span-2"><span class="hint">Kosongkan keduanya bila belum ada informasi resmi. Tanggal/waktu ditampilkan dalam ${TZ}.</span></div><div class="form-field span-2"><div id="formError" class="form-error"></div><button class="btn btn-primary" type="submit">Simpan pengaturan lokal</button></div></form></section><section class="panel setting-section"><h3>Integrasi dan data</h3><p>Belum terhubung dengan layanan eksternal apa pun.</p><div class="setting-line"><span>WhatsApp otomatis</span><strong>Belum tersedia</strong></div><div class="setting-line"><span>Backend Go</span><strong>Belum terhubung</strong></div><div class="setting-line"><span>Booking website</span><strong>Belum tersedia</strong></div><div class="setting-line"><span>Penyimpanan</span><strong>Browser lokal</strong></div></section><section class="panel setting-section"><h3>Aturan penting</h3><p>Aturan minimum untuk dikembangkan menjadi sistem produksi.</p><div class="notice"><strong>1 mobil = 1 peserta</strong> pada waktu yang sama. Hindari double-booking instruktur maupun mobil, dan validasi ulang pada server sebelum menyimpan transaksi sesungguhnya.</div><button class="btn btn-quiet" style="margin-top:16px" data-action="reset-demo">${ico('rotate','sm')} Kembalikan data simulasi</button></section></div>`;}
  function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3600);}
  function closeMenu(){document.getElementById('sidebar').classList.remove('open');document.getElementById('scrim').classList.remove('open');document.querySelector('.mobile-menu-btn').setAttribute('aria-expanded','false');}
  function navigate(page){if(!labels[page])return;ui.page=page;history.pushState(null,'',`/schools/${activeSchool.id}/dashboard/${page}`);ui.query='';ui.studentQuery='';closeMenu();closeModal();window.scrollTo({top:0,behavior:'instant'});render();}
  const field=(label,name,type='text',required=false,value='',extra='')=>`<div class="form-field"><label for="f-${name}">${label}${required?' *':''}</label><input type="${type}" name="${name}" id="f-${name}" value="${attr(value)}" ${required?'required':''} ${extra}/></div>`;
  const selectField=(label,name,opts,value='',required=true)=>`<div class="form-field"><label for="f-${name}">${label}${required?' *':''}</label><select name="${name}" id="f-${name}" ${required?'required':''}>${opts.map(o=>{const v=typeof o==='string'?o:o.value;const l=typeof o==='string'?o:o.label;return `<option value="${attr(v)}" ${v===value?'selected':''}>${esc(l)}</option>`;}).join('')}</select></div>`;
  let modalReturnFocus=null;
  function modal(title,desc,body,buttons=''){modalReturnFocus=document.activeElement;document.getElementById('modalRoot').innerHTML=`<div class="modal-wrap" data-action="outside-modal"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modal-head"><div><h2 id="modalTitle">${title}</h2><p>${desc}</p></div><button class="icon-control" type="button" data-action="close-modal" aria-label="Tutup dialog">${ico('x','sm')}</button></div>${body}${buttons}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>document.querySelector('.modal input,.modal select,.modal button')?.focus(),0);}
  function closeModal(){const wasOpen=Boolean(document.getElementById('modalRoot').innerHTML);document.getElementById('modalRoot').innerHTML='';document.body.style.overflow='';if(wasOpen&&modalReturnFocus?.isConnected)modalReturnFocus.focus();modalReturnFocus=null;}
  function modalForm(formName,fields,submitText='Simpan contoh'){modal('', '',`<form data-form="${formName}"><div class="modal-content"><div class="form-grid">${fields}</div><div class="form-error" id="modalError" role="alert" style="margin-top:14px"></div></div><div class="modal-foot"><button type="button" class="btn btn-quiet" data-action="close-modal">Batal</button><button type="submit" class="btn btn-primary">${esc(submitText)}</button></div></form>`);}
  function addLead(){modal('Tambah permintaan','Catat calon murid secara manual. Tidak mengirim WhatsApp.',`<form data-form="add-lead"><div class="modal-content"><div class="form-grid">${field('Nama calon murid','name','text',true,'','maxlength="70"')}${field('WhatsApp (opsional)','phone','tel',false,'','placeholder="08xxxxxxxxxx" inputmode="tel"')}${selectField('Jenis transmisi','trans',['Matic','Manual','Kombinasi'])}${selectField('Minat paket','package',['Belum ditentukan','Pemanasan (demo)','Makin Lancar (demo)','Siap Jalan (demo)'])}${selectField('Preferensi waktu','time',['Belum ditentukan','Pagi','Siang','Sore','Malam','Akhir pekan'])}<div class="form-field"><label for="f-source">Sumber</label><select id="f-source" name="source"><option>WhatsApp (manual)</option><option>Input admin</option></select></div><div class="form-field span-2"><label for="f-notes">Catatan (opsional)</label><textarea id="f-notes" name="notes" placeholder="Tuliskan kebutuhan atau preferensi..."></textarea></div></div><div id="modalError" class="form-error" role="alert" style="margin-top:14px"></div></div><div class="modal-foot"><button type="button" class="btn btn-quiet" data-action="close-modal">Batal</button><button class="btn btn-primary" type="submit">Simpan permintaan</button></div></form>`);}
  function addStudent(){modal('Tambah murid','Input peserta untuk simulasi penjadwalan.',`<form data-form="add-student"><div class="modal-content"><div class="form-grid">${field('Nama murid','name','text',true,'','maxlength="70"')}${field('WhatsApp (opsional)','phone','tel')}${selectField('Paket contoh','package',['Pemanasan · Matic','Pemanasan · Manual','Makin Lancar · Matic','Makin Lancar · Manual','Siap Jalan · Matic','Siap Jalan · Manual'])}${field('Jumlah sesi paket (contoh)','total','number',true,'4','min="1" max="100"')}<div class="form-field span-2"><p class="hint">Jumlah sesi merupakan input simulasi admin, bukan ketentuan paket resmi.</p></div></div><div id="modalError" class="form-error" role="alert" style="margin-top:14px"></div></div><div class="modal-foot"><button type="button" class="btn btn-quiet" data-action="close-modal">Batal</button><button class="btn btn-primary" type="submit">Tambah murid</button></div></form>`);}
  function instructorForm(existing=null){modal(existing?'Ubah instruktur':'Tambah instruktur','Data hanya tersimpan di browser ini.',`<form data-form="save-instructor" data-edit-id="${attr(existing?.id||'')}"><div class="modal-content"><div class="form-grid">${field('Nama instruktur','name','text',true,existing?.name||'','maxlength="70"')}${selectField('Kompetensi','skills',['Matic','Manual','Matic & Manual'],existing?.skills||'Matic')}${selectField('Status','active',[{value:'true',label:'Aktif'},{value:'false',label:'Nonaktif'}],String(existing?.active??true))}<div class="form-field span-2"><label for="f-notes">Catatan (opsional)</label><textarea id="f-notes" name="notes" maxlength="300">${esc(existing?.notes||'')}</textarea></div></div><div id="modalError" class="form-error" role="alert" style="margin-top:14px"></div></div><div class="modal-foot"><button type="button" class="btn btn-quiet" data-action="close-modal">Batal</button><button class="btn btn-primary" type="submit">Simpan instruktur</button></div></form>`);}
  function sessionForm(existing=null,studentId=''){
    const isEdit=Boolean(existing); const current=existing||{studentId:studentId||db.students[0]?.id||'',date:ui.date,start:'',end:'',trans:'Matic',instructorId:'',carId:'',status:'Menunggu konfirmasi'};
    const studentOptions=[{value:'',label:'Pilih murid'},...db.students.filter(s=>s.status==='Aktif'||s.id===current.studentId).map(s=>({value:s.id,label:s.name}))];
    const teacherOptions=[{value:'',label:'Pilih instruktur'},...db.instructors.filter(i=>i.active||i.id===current.instructorId).map(i=>({value:i.id,label:i.name+' · '+i.skills}))];
    const carOptions=[{value:'',label:'Pilih mobil'},...db.cars.filter(c=>c.active||c.id===current.carId).map(c=>({value:c.id,label:c.name+' · '+c.trans}))];
    modal(isEdit?'Jadwalkan ulang sesi':'Jadwalkan sesi baru','Pemeriksaan bentrok dilakukan di browser. Tidak membuat reservasi nyata.',`<form data-form="save-session" data-edit-id="${attr(existing?.id||'')}"><div class="modal-content"><div class="form-grid">${selectField('Murid','studentId',studentOptions,current.studentId)}${selectField('Transmisi','trans',['Matic','Manual'],current.trans)}${field('Tanggal sesi','date','date',true,current.date)}${selectField('Status','status',['Menunggu konfirmasi','Terkonfirmasi'],isEdit&&current.status==='Terkonfirmasi'?'Terkonfirmasi':'Menunggu konfirmasi')}${field('Mulai (WITA)','start','time',true,current.start)}${field('Selesai (WITA)','end','time',true,current.end)}${selectField('Instruktur','instructorId',teacherOptions,current.instructorId)}${selectField('Mobil','carId',carOptions,current.carId)}<div class="form-field span-2"><p class="hint">Durasi tidak ditentukan otomatis karena aturan paket belum terverifikasi. Pastikan kedua sumber daya tersedia.</p></div></div><div id="modalError" class="form-error" role="alert" style="margin-top:14px"></div></div><div class="modal-foot"><button type="button" class="btn btn-quiet" data-action="close-modal">Batal</button><button type="submit" class="btn btn-primary">${isEdit?'Simpan perubahan':'Simpan sesi demo'}</button></div></form>`);
  }
  function showLead(id){const l=db.leads.find(x=>x.id===id);if(!l)return;const phone=String(l.phone||'').replace(/\D/g,'');const waOk=/^(?:62|0)8\d{8,12}$/.test(phone);const details=[['Nama',l.name],['WhatsApp',l.phone||'Belum disimpan'],['Minat kursus',l.interest],['Preferensi waktu',l.time||'Belum dipilih'],['Sumber',l.source],['Diterima',smallDate(l.date)],['Catatan',l.notes||'—']];modal(esc(l.name),'Detail permintaan · input manual / data simulasi',`<div class="modal-content"><div style="margin-bottom:12px">${badgeStatus(l.status)}</div>${details.map(([a,b])=>`<div class="detail-row"><span>${esc(a)}</span><strong>${esc(b)}</strong></div>`).join('')}<div class="form-field" style="margin-top:18px"><label for="leadNextStatus">Perbarui status</label><select id="leadNextStatus">${['Baru','Dihubungi','Menunggu keputusan','Dikonversi','Tidak lanjut'].map(s=>`<option ${s===l.status?'selected':''}>${s}</option>`).join('')}</select><span class="hint">Membuka WhatsApp tidak otomatis mengubah status. Simpan perubahan secara terpisah.</span></div></div>`,`<div class="modal-foot"><button class="btn btn-quiet" data-action="save-lead-status" data-id="${attr(l.id)}">Simpan status</button><button class="btn btn-quiet" data-action="whatsapp-lead" data-id="${attr(l.id)}" ${waOk?'':'disabled title="Masukkan nomor WA valid lebih dulu"'}>${ico('phone','sm')} WhatsApp</button><button class="btn btn-primary" data-action="lead-to-student" data-id="${attr(l.id)}">Jadikan murid</button></div>`);}
  function showStudent(id){const s=getStudent(id);if(!s)return;const upcoming=orderedSessions(db.sessions.filter(x=>x.studentId===id&&x.date>=isoDay()&&!['Dibatalkan','Selesai'].includes(x.status)));modal(esc(s.name),'Data peserta simulasi',`<div class="modal-content">${[['Paket',s.package],['Status',s.status],['Progres tercatat',`${s.done} dari ${s.total} sesi (demo)`],['WhatsApp',s.phone||'Belum disimpan'],['Sesi berikutnya',upcoming.length?`${smallDate(upcoming[0].date)} · ${upcoming[0].start} ${TZ}`:'Belum ada']].map(([k,v])=>`<div class="detail-row"><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join('')}<div style="margin-top:18px"><strong style="font-size:12px">Riwayat jadwal</strong>${orderedSessions(db.sessions.filter(x=>x.studentId===s.id)).map(x=>`<div class="detail-row"><span>${smallDate(x.date)} · ${x.start}</span>${badgeStatus(x.status)}</div>`).join('')||'<p class="muted" style="font-size:11px;margin-top:9px">Belum ada sesi</p>'}</div></div>`,`<div class="modal-foot"><button class="btn btn-quiet" data-action="close-modal">Tutup</button><button class="btn btn-primary" data-action="schedule-student" data-id="${attr(s.id)}">${ico('plus','sm')} Jadwalkan sesi</button></div>`);}
  function showSession(id){const s=db.sessions.find(x=>x.id===id);if(!s)return;modal('Detail sesi','Data jadwal simulasi · waktu Asia/Makassar (WITA)',`<div class="modal-content"><div style="margin-bottom:13px">${badgeStatus(s.status)}</div>${[['Murid',studentName(s.studentId)],['Tanggal',fmtDate(s.date)],['Waktu',`${s.start}–${s.end} WITA`],['Transmisi',s.trans],['Instruktur',instrName(s.instructorId)],['Mobil',carName(s.carId)]].map(([a,b])=>`<div class="detail-row"><span>${esc(a)}</span><strong>${esc(b)}</strong></div>`).join('')}<p style="font-size:11px;color:#8D887F;line-height:1.7;margin:15px 0 0">Perubahan di sini tidak mengirim pesan kepada murid dan tidak membuat booking nyata.</p></div>`,`<div class="modal-foot"><button class="btn btn-quiet" data-action="edit-session" data-id="${attr(s.id)}">${ico('edit','sm')} Ubah waktu</button>${s.status==='Menunggu konfirmasi'?`<button class="btn btn-primary" data-action="set-session-status" data-id="${attr(s.id)}" data-status="Terkonfirmasi">Konfirmasi demo</button>`:''}${s.status==='Terkonfirmasi'?`<button class="btn btn-primary" data-action="set-session-status" data-id="${attr(s.id)}" data-status="Selesai">Tandai selesai</button>`:''}${!['Selesai','Dibatalkan'].includes(s.status)?`<button class="btn btn-danger" data-action="set-session-status" data-id="${attr(s.id)}" data-status="Dibatalkan">Batalkan</button>`:''}</div>`);}
  function showResource(kind,id){const resource=(kind==='instructor'?db.instructors:db.cars).find(x=>x.id===id);if(!resource)return;const sessions=orderedSessions(db.sessions.filter(x=>(kind==='instructor'?x.instructorId:x.carId)===id&&x.date>=isoDay()&&x.status!=='Dibatalkan'));modal(esc(resource.name),kind==='instructor'?'Detail instruktur (simulasi)':'Detail kendaraan (simulasi)',`<div class="modal-content">${[['Status',resource.active?'Aktif':'Nonaktif'],[kind==='instructor'?'Kompetensi':'Transmisi',resource.skills||resource.trans],['Sesi mendatang',sessions.length+' sesi']].map(([k,v])=>`<div class="detail-row"><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join('')}<h3 style="font-size:12px;margin:20px 0 6px">Penugasan mendatang</h3>${sessions.length?sessions.map(s=>`<div class="detail-row"><span>${smallDate(s.date)} · ${s.start}</span><strong>${esc(studentName(s.studentId))}</strong></div>`).join(''):'<p class="muted" style="font-size:11px">Belum ada</p>'}<p class="muted" style="margin:14px 0 0;font-size:10px">Untuk demo, nonaktifkan hanya jika tidak ada sesi terjadwal mendatang.</p></div>`,`<div class="modal-foot"><button class="btn btn-quiet" data-action="close-modal">Tutup</button><button class="btn ${resource.active?'btn-danger':'btn-primary'}" data-action="toggle-resource" data-kind="${kind}" data-id="${attr(id)}">${resource.active?'Nonaktifkan':'Aktifkan'}</button></div>`);}
  function showError(form,msg){const el=form.querySelector('#modalError,#formError');if(el){el.textContent=msg;el.classList.add('visible');}else toast(msg);}
  const digits=v=>String(v||'').replace(/[^\d]/g,'');
  function validatePhone(v){if(!v)return true;return /^(?:62|0)8\d{8,12}$/.test(digits(v));}
  function validateSession(s,editId=''){
    if(!getStudent(s.studentId)||!s.date||!s.start||!s.end||!s.instructorId||!s.carId)return 'Isi seluruh data sesi, termasuk instruktur dan mobil.';
    if(s.start>=s.end)return 'Jam selesai harus lebih besar dari jam mulai.';
    const i=getInstructor(s.instructorId),c=getCar(s.carId);
    if(!i?.active||!c?.active)return 'Instruktur atau mobil sedang nonaktif. Pilih sumber daya aktif.';
    if(c.trans!==s.trans)return `${c.name} menggunakan transmisi ${c.trans}. Pilih mobil ${s.trans}.`;
    if(i.skills!=='Matic & Manual'&&i.skills!==s.trans)return `${i.name} tidak tersedia untuk transmisi ${s.trans}.`;
    const {hoursFrom,hoursTo}=db.settings;
    if(hoursFrom&&hoursTo&&(s.start<hoursFrom||s.end>hoursTo))return `Jam sesi di luar jam layanan demo (${hoursFrom}–${hoursTo} ${TZ}).`;
    const overlap=db.sessions.find(x=>x.id!==editId&&x.date===s.date&&!['Dibatalkan','Tidak hadir'].includes(x.status)&&s.start<x.end&&s.end>x.start&&(x.instructorId===s.instructorId||x.carId===s.carId||x.studentId===s.studentId));
    if(overlap){const conflict=overlap.instructorId===s.instructorId?`Instruktur ${instrName(s.instructorId)}`:overlap.carId===s.carId?`Mobil ${carName(s.carId)}`:`Murid ${studentName(s.studentId)}`;return `${conflict} sudah terjadwal pada ${overlap.start}–${overlap.end} ${TZ}. Pilih waktu atau sumber daya lain.`;}
    return '';
  }
  function confirmPopup(title,msg,action,opts=''){modal(esc(title),esc(msg),`<div class="modal-content"><p class="muted" style="font-size:12px;line-height:1.8;margin:0">${esc(opts||'Perubahan hanya berlaku pada prototipe lokal ini.')}</p></div>`,`<div class="modal-foot"><button class="btn btn-quiet" data-action="close-modal">Kembali</button><button class="btn btn-danger" type="button" data-action="${attr(action)}">Ya, lanjutkan</button></div>`);}
  function checkSessionStatus(id,status){const s=db.sessions.find(x=>x.id===id);if(!s)return;if(status==='Terkonfirmasi'){const error=validateSession(s,id);if(error){toast(error);return;}}if(status==='Dibatalkan'){modal('Batalkan sesi contoh?','Status sesi ini akan menjadi Dibatalkan.',`<div class="modal-content"><div class="notice">Murid tidak menerima notifikasi otomatis. Pastikan komunikasi manual jika digunakan di sistem nyata.</div></div>`,`<div class="modal-foot"><button class="btn btn-quiet" data-action="close-modal">Kembali</button><button class="btn btn-danger" data-action="commit-status" data-id="${attr(id)}" data-status="Dibatalkan">Batalkan sesi</button></div>`);return;}commitStatus(id,status);}
  function commitStatus(id,status){const s=db.sessions.find(x=>x.id===id);if(!s)return;s.status=status;if(status==='Selesai'){const student=getStudent(s.studentId);if(student){student.done=Math.min(student.total,student.done+1);if(student.done>=student.total)student.status='Selesai';}}persist();closeModal();render();toast(`Status sesi diperbarui menjadi ${status} (demo).`);}
  document.addEventListener('click',(e)=>{
    const target=e.target.closest('[data-action],[data-page],[data-view],[data-lead],[data-student],[data-session],[data-instructor],[data-car]');if(!target)return;
    if(target.dataset.page){navigate(target.dataset.page);return;}
    if(target.dataset.view){ui.view=target.dataset.view;render();return;}
    if(target.dataset.lead){showLead(target.dataset.lead);return;}
    if(target.dataset.student){showStudent(target.dataset.student);return;}
    if(target.dataset.session){showSession(target.dataset.session);return;}
    if(target.dataset.instructor){showResource('instructor',target.dataset.instructor);return;}
    if(target.dataset.car){showResource('car',target.dataset.car);return;}
    const a=target.dataset.action, id=target.dataset.id;
    if(a==='outside-modal'){if(e.target===target)closeModal();return;}
    if(a==='close-modal'){closeModal();return;}
    if(a==='toggle-menu'){const open=document.getElementById('sidebar').classList.toggle('open');document.getElementById('scrim').classList.toggle('open',open);target.setAttribute('aria-expanded',String(open));return;}
    if(a==='close-menu'){closeMenu();return;}
    if(a==='add-lead'){addLead();return;}
    if(a==='add-student'){addStudent();return;}
    if(a==='add-instructor'){instructorForm();return;}
    if(a==='sort-instructor'){const key=target.dataset.sort;ui.instructorDirection=ui.instructorSort===key&&ui.instructorDirection==='asc'?'desc':'asc';ui.instructorSort=key;ui.instructorPage=1;render();return;}
    if(a==='instructor-page'){ui.instructorPage=Number(target.dataset.pageNumber);render();return;}
    if(a==='edit-instructor'){const instructor=getInstructor(id);if(instructor)instructorForm(instructor);return;}
    if(a==='delete-instructor'){const instructor=getInstructor(id);if(!instructor)return;if(db.sessions.some(s=>s.instructorId===id)){modal('Instruktur masih dipakai','Instruktur ini tercatat pada sesi. Hapus atau pindahkan sesi terkait lebih dulu.',`<div class="modal-content"><p class="muted">Riwayat sesi tetap memakai nama instruktur ini.</p></div>`,`<div class="modal-foot"><button class="btn btn-primary" data-action="close-modal">Tutup</button></div>`);return;}modal('Hapus instruktur?',esc(instructor.name),`<div class="modal-content"><p class="muted">Data instruktur ini akan dihapus dari browser ini.</p></div>`,`<div class="modal-foot"><button class="btn btn-quiet" data-action="close-modal">Batal</button><button class="btn btn-danger" data-action="confirm-delete-instructor" data-id="${attr(id)}">Hapus instruktur</button></div>`);return;}
    if(a==='confirm-delete-instructor'){if(db.sessions.some(s=>s.instructorId===id))return;db.instructors=db.instructors.filter(i=>i.id!==id);persist();closeModal();render();toast('Instruktur dihapus dari browser ini.');return;}
    if(a==='add-session'){sessionForm();return;}
    if(a==='profile'){toast('Mode demo tanpa login. Tidak ada akun yang terhubung.');return;}
    if(a==='package-info'){toast('Nama, jumlah sesi, dan harga paket menunggu konfirmasi bisnis.');return;}
    if(a==='clear-filters'){ui.query='';ui.leadStatus='Semua status';ui.leadTrans='Semua jenis';render();return;}
    if(a==='prev-date'||a==='next-date'){ui.date=moveDay(ui.date,(a==='prev-date'?-1:1)*(ui.view==='minggu'?7:1));render();return;}
    if(a==='today'){ui.date=isoDay();render();return;}
    if(a==='reset-demo'){confirmPopup('Reset data simulasi?','Data yang ditambah atau diubah pada browser ini akan diganti dengan contoh awal.','confirm-reset');return;}
    if(a==='confirm-reset'){db=seed();persist();ui.date=isoDay();closeModal();render();toast('Data contoh telah dikembalikan.');return;}
    if(a==='save-lead-status'){const l=db.leads.find(x=>x.id===id);if(l){l.status=document.getElementById('leadNextStatus').value;persist();closeModal();render();toast('Status permintaan diperbarui (demo).');}return;}
    if(a==='whatsapp-lead'){const l=db.leads.find(x=>x.id===id);if(l&&validatePhone(l.phone)&&l.phone){const phone=digits(l.phone).replace(/^0/,'62');window.open(`https://wa.me/${phone}`,'_blank','noopener,noreferrer');}return;}
    if(a==='lead-to-student'){const l=db.leads.find(x=>x.id===id);if(!l)return;let s=db.students.find(x=>x.name.toLowerCase()===l.name.toLowerCase());if(!s){s={id:uid('S'),name:l.name,phone:l.phone,package:l.interest,done:0,total:0,status:'Aktif'};db.students.unshift(s);}l.status='Dikonversi';persist();closeModal();navigate('murid');toast('Murid contoh ditambahkan. Kuota sesi belum ditentukan.');return;}
    if(a==='schedule-student'){closeModal();ui.page='jadwal';render();sessionForm(null,id);return;}
    if(a==='edit-session'){const s=db.sessions.find(x=>x.id===id);if(s)sessionForm(s);return;}
    if(a==='set-session-status'){checkSessionStatus(id,target.dataset.status);return;}
    if(a==='commit-status'){commitStatus(id,target.dataset.status);return;}
    if(a==='toggle-resource'){const arr=target.dataset.kind==='instructor'?db.instructors:db.cars;const r=arr.find(x=>x.id===id);if(!r)return;const future=db.sessions.some(s=>s.date>=isoDay()&&!['Dibatalkan','Selesai'].includes(s.status)&&(target.dataset.kind==='instructor'?s.instructorId:s.carId)===id);if(r.active&&future){toast('Tidak bisa menonaktifkan: masih ada sesi mendatang yang memakai resource ini.');return;}r.active=!r.active;persist();closeModal();render();toast('Status sumber daya diperbarui (demo).');return;}
  });
  document.addEventListener('change',e=>{const t=e.target;if(t.id==='leadStatus'){ui.leadStatus=t.value;render();}if(t.id==='leadTrans'){ui.leadTrans=t.value;render();}if(t.id==='scheduleFilter'){ui.scheduleFilter=t.value;render();}});
  document.addEventListener('input',e=>{const t=e.target;if(!['leadSearch','studentSearch','instructorSearch'].includes(t.id))return;const start=t.selectionStart,end=t.selectionEnd; if(t.id==='leadSearch')ui.query=t.value; else if(t.id==='studentSearch')ui.studentQuery=t.value;else{ui.instructorQuery=t.value;ui.instructorPage=1;}render();const next=document.getElementById(t.id);if(next){next.focus();try{next.setSelectionRange(start,end);}catch(err){}}});
  document.getElementById('globalSearch').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();ui.query=e.target.value;ui.studentQuery=e.target.value;navigate('permintaan');ui.query=e.target.value;render();}});
  document.addEventListener('submit',e=>{
    const f=e.target.closest('form[data-form]');if(!f)return;e.preventDefault();const data=Object.fromEntries(new FormData(f).entries());
    if(f.dataset.form==='add-lead'){
      if(!validatePhone(data.phone))return showError(f,'Nomor WhatsApp harus dimulai 08 atau 628 dengan panjang yang sesuai.');
      db.leads.unshift({id:uid('L'),name:data.name.trim(),phone:data.phone.trim(),interest:data.trans+(data.package!=='Belum ditentukan'?' · '+data.package:''),time:data.time,status:'Baru',source:data.source,date:isoDay(),notes:data.notes.trim()});persist();closeModal();ui.page='permintaan';render();toast('Permintaan tersimpan di browser ini (demo).');return;
    }
    if(f.dataset.form==='add-student'){
      if(!validatePhone(data.phone))return showError(f,'Nomor WhatsApp tidak sesuai format.');
      db.students.unshift({id:uid('S'),name:data.name.trim(),phone:data.phone.trim(),package:data.package,done:0,total:Number(data.total),status:'Aktif'});persist();closeModal();ui.page='murid';render();toast('Murid ditambahkan ke data demo.');return;
    }
    if(f.dataset.form==='save-instructor'){
      const name=String(data.name||'').trim(),skills=String(data.skills||''),notes=String(data.notes||'').trim(),active=data.active==='true';
      if(!name)return showError(f,'Nama instruktur wajib diisi.');
      const existing=f.dataset.editId?getInstructor(f.dataset.editId):null;
      if(f.dataset.editId&&!existing)return showError(f,'Instruktur tidak ditemukan.');
      const assigned=existing?db.sessions.filter(s=>s.instructorId===existing.id):[];
      if(assigned.some(s=>skills!=='Matic & Manual'&&s.trans!==skills))return showError(f,'Kompetensi tidak cocok dengan sesi yang sudah tercatat.');
      if(existing?.active&& !active && assigned.some(s=>s.date>=isoDay()&&!['Dibatalkan','Selesai'].includes(s.status)))return showError(f,'Instruktur masih memiliki sesi mendatang.');
      if(existing)Object.assign(existing,{name,skills,notes,active});else db.instructors.unshift({id:uid('I'),name,skills,notes,active});
      persist();closeModal();render();toast('Instruktur tersimpan di browser ini.');return;
    }
    if(f.dataset.form==='save-session'){
      const next={studentId:data.studentId,date:data.date,start:data.start,end:data.end,trans:data.trans,instructorId:data.instructorId,carId:data.carId,status:data.status};const error=validateSession(next,f.dataset.editId);if(error)return showError(f,error);
      if(f.dataset.editId){const old=db.sessions.find(s=>s.id===f.dataset.editId);if(old)Object.assign(old,next);}else db.sessions.push({id:uid('B'),...next});persist();ui.date=data.date;closeModal();ui.page='jadwal';render();toast('Jadwal disimpan di browser (demo), bukan booking nyata.');return;
    }
    if(f.dataset.form==='settings'){
      if(Boolean(data.hoursFrom)!==Boolean(data.hoursTo))return showError(f,'Masukkan kedua jam atau kosongkan keduanya.');
      if(data.hoursFrom&&data.hoursFrom>=data.hoursTo)return showError(f,'Jam akhir harus setelah jam mulai.');
      db.settings.hoursFrom=data.hoursFrom;db.settings.hoursTo=data.hoursTo;persist();render();toast('Pengaturan lokal tersimpan (demo).');return;
    }
  });
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(document.getElementById('modalRoot').innerHTML)closeModal();else closeMenu();}if(e.key==='Tab'){const dialog=document.querySelector('.modal');if(!dialog)return;const items=[...dialog.querySelectorAll('button:not(:disabled), input:not(:disabled), select:not(:disabled), textarea:not(:disabled), a[href]')];if(!items.length)return;const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
  window.addEventListener('resize',()=>{if(window.innerWidth>850)closeMenu();});
  const picker=document.getElementById('schoolPicker');
  picker.innerHTML=schools.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('');
  const updateSchoolChrome=()=>{picker.value=activeSchool.id;document.getElementById('brandWord').textContent=activeSchool.name;document.getElementById('brandCaption').textContent=`Kursus mengemudi · ${activeSchool.location}`;document.querySelector('.brand-logo').src=activeSchool.logo||'/logo.png';document.querySelector('.brand-logo').style.visibility=activeSchool.logo?'visible':'hidden';};
  picker.addEventListener('change',()=>{activeSchool=schools.find(s=>s.id===picker.value)||schools[0];history.pushState(null,'',`/schools/${activeSchool.id}/dashboard/${ui.page}`);localStorage.setItem('active-demo-school',activeSchool.id);TZ=activeSchool.timeZone;db=readDB();ui.date=isoDay();closeModal();updateSchoolChrome();render();});
  window.addEventListener('popstate',()=>{activeSchool=schools.find(s=>s.id===location.pathname.split('/')[2])||schools[0];TZ=activeSchool.timeZone;db=readDB();ui.page=labels[location.pathname.split('/')[4]]?location.pathname.split('/')[4]:'dashboard';updateSchoolChrome();render();});
  updateSchoolChrome();
  render();
  setInterval(()=>{const el=document.getElementById('headerClock');if(el)el.textContent=`${nowWita()} ${TZ==='Asia/Makassar'?'WITA':TZ==='Asia/Jakarta'?'WIB':TZ}`;},60000);
}
